<!DOCTYPE html><html lang="de"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;font:14px Segoe UI,Arial;background:#f4f6f8;color:#1f2937}.page{max-width:1180px;margin:auto;padding:28px}.card{background:#fff;border-radius:12px;box-shadow:0 2px 8px #0001;padding:20px}.button{display:inline-block;padding:8px 12px;border-radius:7px;background:#0369a1;color:#fff;text-decoration:none}table{width:100%;border-collapse:collapse;margin-top:14px}th,td{padding:9px;border-bottom:1px solid #e5e7eb}th{text-align:left;color:#64748b}.money{text-align:right}.warn{font-weight:bold;color:#b91c1c}</style></head><body><div class="page"><div class="card"><h1>Kontierungsübersicht nach Kundenkonto</h1><form method="get"><label>Von <input type="date" name="von" value="{{ $von }}"></label> <label>Bis <input type="date" name="bis" value="{{ $bis }}"></label> <button>Anzeigen</button></form><table><thead><tr><th>DATEV-Kundenkonto</th><th>Kunde</th><th>Kunden-ID</th><th>Netto</th><th>Steuern</th><th>Brutto</th></tr></thead><tbody>@foreach($groups as $g)<tr><td class="{{ str_contains($g->konto,'SOFORT')?'warn':'' }}">{{ $g->konto }}</td><td>{{ $g->name }}</td><td>{{ $g->kundeID }}</td><td class="money">{{ number_format($g->netto,2,',','.') }} €</td><td class="money">{{ number_format($g->steuer,2,',','.') }} €</td><td class="money">{{ number_format($g->brutto,2,',','.') }} €</td></tr>@endforeach</tbody></table><p><a class="button" href="{{ route('datev.index') }}">Zurück</a></p></div></div><script src="{{ asset('js/db-window-manager.js') }}"></script></body></html>